// ČUVAR NA ULAZU — pre nego što pogledamo ijedan broj.
// Adresa nije lozinka: ko sazna uvoz-adresu, ne sme time da dobije pravo upisa.

const DOZVOLJENI_POSILJAOCI = [
  // e-adrese sa kojih ERP klijenta šalje izveštaj; prazan spisak ne propušta NIKOGA
  'racunovodstvo@klijent.rs',
];
// Gmail upisuje rezultat DKIM provere u zaglavlje. Bez nje se pošiljalac lažira u tri reda koda.
// Ako na radionici sve pada sa „DKIM nepoznat“, pogledaj izlaz trigera (headers) pre nego što isključiš.
const ZAHTEVAJ_DKIM = true;
const DOZVOLJENI_TIPOVI = ['.xlsx', '.xls', '.csv'];

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const posiljalac = (j.from?.value?.[0]?.address ?? '').toLowerCase();
  const auth = String(j.headers?.['authentication-results'] ?? '');
  const prilozi = Object.entries(item.binary ?? {}).filter(([, b]) =>
    DOZVOLJENI_TIPOVI.some((t) => (b.fileName ?? '').toLowerCase().endsWith(t)),
  );

  const meta = {
    posiljalac,
    naslov: j.subject ?? '',
    primljeno: new Date().toISOString(),
    fajl: prilozi[0]?.[1]?.fileName ?? '',
  };

  let razlog = null;
  if (!DOZVOLJENI_POSILJAOCI.map((a) => a.toLowerCase()).includes(posiljalac))
    razlog = `Pošiljalac ${posiljalac || '(nepoznat)'} nije na spisku dozvoljenih`;
  else if (ZAHTEVAJ_DKIM && !/dkim=pass/i.test(auth))
    // nepoznat rezultat se broji kao neuspeh, ne kao prolaz
    razlog = 'DKIM provera nije prošla ili je nepoznata';
  else if (prilozi.length === 0) razlog = 'Nema priloga u formatu .xlsx/.xls/.csv';
  else if (prilozi.length > 1)
    // jedna adresa = jedna vrsta podatka; ne pogađamo koja je tabela prava
    razlog = `Stiglo je ${prilozi.length} tabela, očekuje se tačno jedna`;

  if (razlog) {
    out.push({ json: { ok: false, status: 'odbijeno', razlog, ...meta } });
  } else {
    out.push({ json: { ok: true, ...meta }, binary: { data: prilozi[0][1] } });
  }
}
return out;

// MAPIRANJE I PROVERA — isti tragovi kolona kao u Komanda AI (src/core/import/mapping.ts).
// Pogrešno pogođena kolona se ne vidi kao greška nego kao pogrešan broj, mesecima.
// Zato: fali obavezna kolona → CELA tabela se odbija, ništa se ne upisuje napola.

const POLJA = [
  { kljuc: 'kupac', obavezno: true, tip: 'tekst', tragovi: ['kupac', 'kupc', 'klijent', 'customer', 'partner', 'duznik', 'naziv'] },
  { kljuc: 'iznos', obavezno: true, tip: 'broj', tragovi: ['iznos', 'dug', 'saldo', 'amount', 'balance', 'potrazivanj'] },
  { kljuc: 'dospece', obavezno: true, tip: 'datum', tragovi: ['dospec', 'dospev', 'valuta', 'rok', 'due'] },
  // „broj“ namerno nije trag: hvata i „broj dana“ i „broj komada“
  { kljuc: 'faktura', obavezno: false, tip: 'tekst', tragovi: ['faktur', 'racun', 'invoice', 'dokument'] },
];

const meta = $('Provera pošiljaoca i priloga').first().json;
const svedi = (s) => String(s).toLowerCase()
  .replace(/[čć]/g, 'c').replace(/š/g, 's').replace(/ž/g, 'z').replace(/đ/g, 'dj');

const redovi = $input.all().map((i) => i.json).filter((r) => Object.keys(r).length > 0);
const odbij = (razlog) => [{ json: { ok: false, status: 'odbijeno', razlog, ...meta } }];

if (redovi.length === 0) return odbij('Tabela je prazna');

// 1) Prepoznaj kolone po zaglavlju
const zaglavlje = Object.keys(redovi[0]);
const mapa = {};
for (const p of POLJA) {
  const nadjena = zaglavlje.find((k) => p.tragovi.some((t) => svedi(k).includes(t)) && !Object.values(mapa).includes(k));
  if (nadjena) mapa[p.kljuc] = nadjena;
}
const fale = POLJA.filter((p) => p.obavezno && !mapa[p.kljuc]).map((p) => p.kljuc);
if (fale.length) return odbij(`Nedostaju obavezne kolone: ${fale.join(', ')}. Zaglavlje: ${zaglavlje.join(' | ')}`);

// 2) Pretvori vrednosti (Excel ume da da broj, „184.500,00“ ili datum kao serijski broj)
const broj = (v) => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').trim().replace(/\s/g, '');
  if (!s) return NaN;
  return Number(s.includes(',') ? s.replace(/\./g, '').replace(',', '.') : s);
};
const datum = (v) => {
  if (typeof v === 'number') return new Date(Date.UTC(1899, 11, 30) + v * 86400000).toISOString().slice(0, 10);
  const s = String(v ?? '').trim();
  const m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})\.?$/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  const d = new Date(s);
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
};

const ispravni = [];
const losi = [];
redovi.forEach((r, i) => {
  const red = {
    kupac: String(r[mapa.kupac] ?? '').trim(),
    faktura: mapa.faktura ? String(r[mapa.faktura] ?? '').trim() : '',
    iznos: broj(r[mapa.iznos]),
    dospece: datum(r[mapa.dospece]),
  };
  if (!red.kupac || !Number.isFinite(red.iznos) || !red.dospece) losi.push(i + 2);
  else ispravni.push(red);
});

// Poneki loš red se prijavi; ako je loša većina, tabela je verovatno pogrešna — ne upisujemo je.
if (ispravni.length === 0 || losi.length > redovi.length / 2)
  return odbij(`Neispravno ${losi.length} od ${redovi.length} redova (redovi u Excelu: ${losi.slice(0, 10).join(', ')})`);

return ispravni.map((r) => ({
  json: { ok: true, ...r, izvor: meta.posiljalac, fajl: meta.fajl, primljeno: meta.primljeno, _losiRedovi: losi.join(', ') },
}));

// Jedan red u dnevniku po poruci — i za primljeno i za odbijeno.
// Bez dnevnika odbijena poruka nestaje bez traga: klijent kaže „poslao sam“, sistem „nije stiglo“.
const upisano = $('Tabela ispravna?').all().map((i) => i.json);
const prvi = upisano[0];
const ukupno = upisano.reduce((s, r) => s + r.iznos, 0);
return [{
  json: {
    primljeno: prvi.primljeno,
    vrsta: 'potrazivanja',
    status: 'primljeno',
    posiljalac: prvi.izvor,
    fajl: prvi.fajl,
    redova: upisano.length,
    ukupno: Math.round(ukupno * 100) / 100,
    razlog: prvi._losiRedovi ? `Preskočeni redovi: ${prvi._losiRedovi}` : '',
  },
}];

// Oba odbijanja (pošiljalac i tabela) završavaju ovde, u istom obliku.
return $input.all().map(({ json: j }) => ({ json: {
  primljeno: j.primljeno, vrsta: 'potrazivanja', status: 'odbijeno',
  posiljalac: j.posiljalac, fajl: j.fajl, redova: 0, ukupno: 0, razlog: j.razlog,
} }));

