// STRAŽA TIŠINE — najopasniji kvar nije pogrešan broj nego broj koji nije stigao.
// Kada izvoz ne stigne, ništa ne pukne: tabla mirno prikazuje jučerašnje brojeve kao današnje.
// Očekivanje se zapisuje UNAPRED: radnim danima do 08:00, uz 30 min tolerancije (Europe/Belgrade).

const RADNI_DANI = [1, 2, 3, 4, 5];   // pon–pet (Luxon: 1 = ponedeljak)
const ROK = { hour: 8, minute: 0 };
const TOLERANCIJA_MIN = 30;

const sada = $now.setZone('Europe/Belgrade');
const primljeni = $input.all().map((i) => i.json)
  .filter((r) => r.status === 'primljeno' && r.vrsta === 'potrazivanja' && r.primljeno)
  .map((r) => DateTime.fromISO(r.primljeno).setZone('Europe/Belgrade'))
  .sort((a, b) => b.toMillis() - a.toMillis());

// Koliko je očekivanih rokova prošlo od poslednjeg prijema?
const poslednji = primljeni[0];
let propusteno = 0;
let dan = sada.startOf('day');
for (let k = 0; k < 14; k++, dan = dan.minus({ days: 1 })) {
  if (!RADNI_DANI.includes(dan.weekday)) continue;
  const rok = dan.set(ROK).plus({ minutes: TOLERANCIJA_MIN });
  if (rok > sada) continue;                       // današnji rok još nije prošao
  const stiglo = primljeni.some((p) => p.hasSame(dan, 'day') && p <= rok.plus({ hours: 12 }));
  if (stiglo) break;
  propusteno++;
}

let presuda = 'u redu';
if (!poslednji) presuda = 'nikad nije stiglo';   // dotok nije ni uspostavljen → proveri podešavanje
else if (propusteno >= 2) presuda = 'ne stiže'; // brojevima se više ne veruje
else if (propusteno === 1) presuda = 'kasni';   // izvoz verovatno nije pokrenut

return [{ json: {
  presuda,
  alarm: presuda !== 'u redu',
  propustenoRokova: propusteno,
  poslednjiPrijem: poslednji ? poslednji.toFormat('dd.MM.yyyy HH:mm') : '—',
  provereno: sada.toFormat('dd.MM.yyyy HH:mm'),
} }];

